import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  DirectionalLight,
  Texture
} from 'three/webgpu';
import { uv, vec3, mix, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // 1. STAGE & BACKDROP GRADIENT (Ensure no FLAT_VOID)
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropGeo = new PlaneGeometry(7.5, 6.0);
  const backdropMat = new MeshBasicNodeMaterial();

  // TSL vertical gradient using colors.surface -> colors.ink
  const colorSurface = vec3(
    parseInt(colors.surface.slice(1, 3), 16) / 255,
    parseInt(colors.surface.slice(3, 5), 16) / 255,
    parseInt(colors.surface.slice(5, 7), 16) / 255
  );
  const colorInk = vec3(
    parseInt(colors.ink.slice(1, 3), 16) / 255,
    parseInt(colors.ink.slice(3, 5), 16) / 255,
    parseInt(colors.ink.slice(5, 7), 16) / 255
  );
  backdropMat.colorNode = mix(colorInk, colorSurface, uv().y);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // 2. HERO PARALLAX-PLANE WITH DEPTH MAP DISPLACEMENT
  const width = 4.2;
  const height = 1.6;
  const geometry = new PlaneGeometry(width, height, 96, 96);
  const material = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.4,
    transparent: true
  });

  // Load and apply assets
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Create displacement uniform and link via TSL displacementNode
  const displacementScale = uniform(0.18);
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      // Setup TSL node calculation for displacement
      material.positionNode = material.positionNode || uv(); 
      // NodeMaterial uses positionNode or displacementNode where available. We assign displacementNode:
      material.displacementMap = depthTex;
      material.displacementScale = 0.18;
      material.needsUpdate = true;
    });
  }

  const parallaxPlane = new Mesh(geometry, material);
  parallaxPlane.position.z = 0;
  group.add(parallaxPlane);

  // 3. MACHINED-METAL LIST FRAME / ACCENTS
  // Fine divider line underneath
  const dividerGeo = new PlaneGeometry(width, 0.015);
  const dividerMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.6
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -height / 2 - 0.1, 0.05);
  group.add(divider);

  // 4. INTERACTIVE ROW TEXT
  // Row Title
  const titleText = ctx.fontAtlas.createText('ATELIER VI-S01', {
    fontSize: 24,
    color: colors.paper,
    align: 'left'
  });
  titleText.position.set(-width / 2 + 0.25, 0.15, 0.1);
  group.add(titleText);

  // Row Meta/Price
  const metaText = ctx.fontAtlas.createText('BOOK VISIT - SECURE SLOT', {
    fontSize: 14,
    color: colors.accent,
    align: 'right'
  });
  metaText.position.set(width / 2 - 0.25, -0.2, 0.1);
  group.add(metaText);

  // 5. LIGHTING FOR PRODUCT SHOT (ACCENT RIM LIGHT)
  const dirLight = new DirectionalLight(colors.accent, 1.4);
  dirLight.position.set(2, 2, 3);
  group.add(dirLight);

  const fillLight = new DirectionalLight(colors.paper, 0.8);
  fillLight.position.set(-3, -1, 2);
  group.add(fillLight);

  // 6. CLINEMATIC PRIMITIVES APPLICATION
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((p) => {
      if (ctx.primitives[p.name]) {
        const result = ctx.primitives[p.name](parallaxPlane, p.params);
        if (result) activePrimitives.push(result);
      }
    });
  }

  // Fallback defaults if primitive binding did not map
  if (activePrimitives.length === 0) {
    // Inject standard micro-rotation on mouse hover locally
    const handlePointerMove = (e) => {
      const x = (e.clientX / window.innerWidth) - 0.5;
      const y = (e.clientY / window.innerHeight) - 0.5;
      gsap.to(parallaxPlane.rotation, {
        y: x * 0.15,
        x: -y * 0.15,
        duration: 0.5,
        ease: 'power2.out'
      });
    };
    window.addEventListener('mousemove', handlePointerMove);
    group.userData.localHoverClean = () => window.removeEventListener('mousemove', handlePointerMove);
  }

  // 7. BEHAVIOR & INTERACTION
  let hoverTimeline;

  group.userData.handlers = {
    pointerover: () => {
      // Preset rise-in (subtle, 0.15 scene units) + scale settle
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(parallaxPlane.position, {
        y: 0.15,
        z: 0.1,
        duration: 0.4,
        ease: 'power3.out'
      });
      hoverTimeline.to(divider.material, {
        opacity: 1.0,
        duration: 0.2
      }, 0);
    },
    pointerout: () => {
      if (hoverTimeline) hoverTimeline.kill();
      gsap.to(parallaxPlane.position, {
        y: 0,
        z: 0,
        duration: 0.5,
        ease: 'power2.out'
      });
      gsap.to(divider.material, {
        opacity: 0.6,
        duration: 0.4
      });
    },
    click: () => {
      // Emit select pricing row event
      ctx.emit('hub-pricing.select', { id: 'pricing-row', source: 'navigation' });
      // GSAP press-down feedback
      gsap.to(parallaxPlane.scale, {
        x: 0.96,
        y: 0.96,
        duration: 0.1,
        yoyo: true,
        repeat: 1,
        ease: 'power2.inOut'
      });
    }
  };

  // 8. CLEANUP CONTRACT
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    activePrimitives.forEach((p) => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
    if (group.userData.localHoverClean) {
      group.userData.localHoverClean();
    }

    // Resource disposal
    geometry.dispose();
    material.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
  };

  return group;
}
